/* Service worker generated by scripts/generate-sw.mjs. Same-origin only; no third-party requests. */
const VERSION = __VERSION__;
const BASE = __BASE__;
const PRECACHE = __PRECACHE__;
const CACHE = `chord-flags-${VERSION}`;
const KEEP_PREVIOUS = 1;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Keep the newest previous cache so a page that is still open can finish loading its chunks.
      const names = (await caches.keys()).filter((n) => n.startsWith("chord-flags-") && n !== CACHE);
      const stamps = await Promise.all(names.map(async (n) => [n, (await (await caches.open(n)).match(`${BASE}/sw-stamp`))?.headers.get("x-at") ?? "0"]));
      stamps.sort((a, b) => Number(b[1]) - Number(a[1]));
      await Promise.all(stamps.slice(KEEP_PREVIOUS).map(([n]) => caches.delete(n)));
      const cache = await caches.open(CACHE);
      await cache.put(`${BASE}/sw-stamp`, new Response("", { headers: { "x-at": String(Date.now()) } }));
      await self.clients.claim();
    })(),
  );
});

function candidates(url) {
  const path = url.pathname;
  if (path.endsWith("/")) return [path + "index.html", path];
  if (/\.[a-z0-9]+$/i.test(path)) return [path];
  return [path + "/index.html", path + ".html", path];
}

async function fromCache(request) {
  const url = new URL(request.url);
  for (const path of candidates(url)) {
    const hit = await caches.match(path, { ignoreSearch: true });
    if (hit) return hit;
  }
  return undefined;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    (async () => {
      const cached = await fromCache(request);
      if (cached) return cached;
      try {
        return await fetch(request);
      } catch (err) {
        if (request.mode === "navigate") {
          const home = await caches.match(`${BASE}/index.html`);
          if (home) return home;
        }
        throw err;
      }
    })(),
  );
});
